'use server'

import { revalidatePath } from 'next/cache';
import { getSupabaseServer, ensureAuthenticated, ensureAdmin } from '@/lib/auth-server';

export async function createRingtoneRequest(formData: {
    movie_name: string;
    song_name: string;
    description?: string;
}) {
    try {
        const { user } = await ensureAuthenticated();
        const { getSupabaseAdmin } = await import('@/lib/auth-server');
        const adminSupabase = await getSupabaseAdmin();
        const { syncUserGamification, POINTS_COST_REQUEST } = await import('@/lib/gamification');

        // 1. Sync first to get latest points
        const stats = await syncUserGamification(adminSupabase, user.id);
        const currentPoints = stats?.points ?? 0;

        // 2. Check if user has enough points
        if (currentPoints < POINTS_COST_REQUEST) {
            return {
                success: false,
                error: `Insufficient points. Requesting a ringtone costs ${POINTS_COST_REQUEST} Rep. You have ${currentPoints} Rep.`
            };
        }

        const supabase = await getSupabaseServer();

        // 3. Insert the request
        const { error } = await supabase
            .from('ringtone_requests')
            .insert({
                user_id: user.id,
                movie_name: formData.movie_name,
                song_name: formData.song_name,
                description: formData.description || null,
                status: 'pending'
            });

        if (error) throw error;

        // 4. Sync again after successful insert to reflect deduction
        await syncUserGamification(adminSupabase, user.id);

        revalidatePath('/requests');
        revalidatePath('/profile');
        return { success: true };
    } catch (e: any) {
        console.error('Request creation failed:', e);
        return { success: false, error: e.message || 'Failed to create request' };
    }
}

export async function fulfillRequest(requestId: string) {
    try {
        await ensureAdmin();
        const { getSupabaseAdmin } = await import('@/lib/auth-server');
        const supabase = await getSupabaseAdmin();

        const { error } = await supabase
            .from('ringtone_requests')
            .update({ status: 'fulfilled' })
            .eq('id', requestId);

        if (error) throw error;

        revalidatePath('/requests');
        return { success: true };
    } catch (e: any) {
        return { success: false, error: e.message };
    }
}

export async function deleteRequest(requestId: string) {
    try {
        const { user } = await ensureAuthenticated();
        const supabase = await getSupabaseServer();

        // RLS will handle permission (only own pending or admin)
        const { error } = await supabase
            .from('ringtone_requests')
            .delete()
            .eq('id', requestId)
            .eq('user_id', user.id); // Simple safety check for users

        if (error) throw error;

        // Recalculate points after deletion
        const { getSupabaseAdmin } = await import('@/lib/auth-server');
        const adminSupabase = await getSupabaseAdmin();
        const { syncUserGamification } = await import('@/lib/gamification');
        await syncUserGamification(adminSupabase, user.id);

        revalidatePath('/requests');
        revalidatePath('/profile');
        return { success: true };
    } catch (e: any) {
        return { success: false, error: e.message };
    }
}

'use server'

import { revalidatePath, revalidateTag } from 'next/cache'
import { ensureAuthenticated, getSupabaseAdmin } from '@/lib/auth-server'
import { db } from '@/lib/db'
import { profiles, withdrawals } from '@/lib/db/schema'
import { eq, and, gte } from 'drizzle-orm'
import { syncUserGamification } from '@/lib/gamification'

// Internal helper for notifications
async function notifyAdminOnWithdrawal(userId: string, amount: number, upiId: string) {
    const webhookUrl = process.env.DISCORD_WEBHOOK_URL;
    if (!webhookUrl) return;

    try {
        await fetch(webhookUrl, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                content: `💰 **Withdrawal Request**\nUser: ${userId}\nAmount: ${amount} Rep\nUPI ID: ${upiId}`,
            })
        });
    } catch (e) {
        console.error('Withdrawal notification failed', e);
    }
}

export async function handleUploadReward(userId: string) {
    // This is technically an triggered action, but we should verify the user matches the session
    const { supabase, user } = await ensureAuthenticated();

    if (user.id !== userId) {
        return { success: false, error: 'Unauthorized: User ID mismatch' };
    }

    // 1. Check if first upload reward already given
    const { data: profile } = await supabase
        .from('profiles')
        .select('is_first_upload_rewarded, points')
        .eq('id', userId)
        .single();

    if (profile && !profile.is_first_upload_rewarded) {
        const adminSupabase = await getSupabaseAdmin();

        // 2. Give 15 Rep bonus immediately
        const { error } = await adminSupabase
            .from('profiles')
            .update({
                is_first_upload_rewarded: true,
                points: (profile.points || 0) + 15
            })
            .eq('id', userId);

        if (error) return { success: false, error };
        return { success: true, bonusGiven: true };
    }

    return { success: true, bonusGiven: false };
}


export async function handleWithdrawal(userId: string, amount: number, upiId: string) {
    const { user } = await ensureAuthenticated();

    if (user.id !== userId) {
        return { success: false, error: 'Unauthorized: User ID mismatch' };
    }

    const adminSupabase = await getSupabaseAdmin();

    // 1. Force Sync first - Ensure profiles.points is actually correct based on current reality
    // (This calculates lifetime - [pending + completed withdrawals])
    const syncResult = await syncUserGamification(adminSupabase, userId);

    if (!syncResult) {
        console.error(`[Withdrawal] Sync failed for user ${userId}`);
        return { success: false, error: 'Failed to synchronize account balance. Please try again.' };
    }

    // 2. Validate withdrawal logic WITHIN ATOMIC TRANSACTION
    const minThreshold = 100;
    if (amount < minThreshold) {
        return { success: false, error: `Minimum withdrawal is ${minThreshold} Rep` };
    }

    const withdrawAmount = amount;

    try {
        console.log(`[Withdrawal] Requesting payout for ${userId}: ${withdrawAmount} Rep`);

        // Use the secure RPC function to handle the atomic transaction
        const { data, error: rpcError } = await adminSupabase.rpc('handle_withdrawal_payout', {
            p_user_id: userId,
            p_amount: withdrawAmount,
            p_upi_id: upiId
        });

        if (rpcError) throw new Error(rpcError.message);

        const result = data as { success: boolean, error?: string };
        if (!result.success) {
            throw new Error(result.error || 'Database transaction failed');
        }

        console.log(`[Withdrawal] Success for ${userId}`);

        // 5. Revalidate
        try {
            revalidatePath('/profile');
            revalidatePath('/admin/withdrawals');
            // @ts-expect-error - revalidateTag has type issues in Next.js 16
            revalidateTag('contributors');
        } catch (e) {
            console.warn('Revalidation failed:', e);
        }

        // 6. Log withdrawal (Notify admin via Discord)
        await notifyAdminOnWithdrawal(userId, withdrawAmount, upiId);

        return { success: true };

    } catch (err: any) {
        console.error('[Withdrawal] Failed:', err.message);
        return { success: false, error: err.message || 'Withdrawal failed. Please try again.' };
    }
}
export async function syncProfileStats(userId: string) {
    try {
        const { user } = await ensureAuthenticated();
        if (user.id !== userId) throw new Error('Unauthorized');

        const adminSupabase = await getSupabaseAdmin();
        const { syncUserGamification } = await import('@/lib/gamification');
        const stats = await syncUserGamification(adminSupabase, userId);

        revalidatePath('/profile');
        return { success: true, stats };
    } catch (e: any) {
        return { success: false, error: e.message };
    }
}

export const revalidate = 3600;
import { searchPerson, getImageUrl } from '@/lib/tmdb';
import RingtoneCard from '@/components/RingtoneCard';
import CompactProfileHeader from '@/components/CompactProfileHeader';
import SortControl from '@/components/SortControl';
import ViewToggle from '@/components/ViewToggle';
import { getArtistBio } from '@/lib/constants';
import Link from 'next/link';
import Image from 'next/image';
import TMDBImage from '@/components/TMDBImage';
import { Ringtone } from '@/types';
import { unstable_cache } from 'next/cache';

const getActorRingtones = unstable_cache(
  async (_actorName: string, _sort: string = 'recent') => {
    // TODO: 'cast' column is missing in the database. Returning empty for now.
    // Once 'cast' column is added, uncomment the query below.
    /*
    let query = supabase
      .from('ringtones')
      .select('*')
      .ilike('cast', `%${actorName}%`);

    // Apply Sorting
    switch (sort) {
      case 'downloads':
        query = query.order('downloads', { ascending: false });
        break;
      case 'likes':
        query = query.order('likes', { ascending: false });
        break;
      case 'year_desc':
        query = query.order('movie_year', { ascending: false });
        break;
      case 'year_asc':
        query = query.order('movie_year', { ascending: true });
        break;
      default: // recent
        query = query.order('created_at', { ascending: false });
    }

    const { data } = await query;
    return data;
    */
    return [] as Ringtone[];
  },
  ['actor-ringtones'],
  { revalidate: 60 }
);

export default async function ActorPage({
  params,
  searchParams
}: {
  params: Promise<{ actor_name: string }>,
  searchParams: Promise<{ sort?: string; view?: string }>
}) {
  const { actor_name } = await params;
  const { sort, view } = await searchParams;
  const actorName = decodeURIComponent(actor_name);
  const currentView = view || 'movies'; // Default to movies

  const ringtones = await getActorRingtones(actorName, sort);

  // Fetch actor image from TMDB
  const person = await searchPerson(actorName);
  const actorImage = person?.profile_path
    ? getImageUrl(person.profile_path, 'w185')
    : ringtones?.find(r => r.poster_url)?.poster_url;

  // Get actor bio
  const actorBio = getArtistBio(actorName);

  // Group by Movies for "Movies" view
  const moviesMap = new Map<string, Ringtone>();
  if (ringtones) {
    ringtones.forEach(r => {
      if (!moviesMap.has(r.movie_name)) {
        moviesMap.set(r.movie_name, r);
      }
    });
  }
  const uniqueMovies = Array.from(moviesMap.values());

  return (
    <div className="max-w-md mx-auto pb-24">
      {/* Sticky Compact Profile Header */}
      <CompactProfileHeader
        name={actorName}
        type="Actor"
        imageUrl={actorImage}
        bio={actorBio}
      />

      {/* Sticky Controls Bar */}
      <div className="sticky top-[120px] z-30 bg-white/95 backdrop-blur-md border-b border-brand-border px-4 py-3 space-y-3 shadow-sm">
        <ViewToggle />
        <div className="flex justify-end">
          <SortControl />
        </div>
      </div>

      <div className="px-4 py-6">
        {ringtones && ringtones.length > 0 ? (
          <>
            {currentView === 'movies' ? (
              /* Movies Grid View */
              <div className="grid grid-cols-2 gap-4">
                {uniqueMovies.map((movie, idx) => (
                  <Link
                    key={movie.movie_name}
                    href={`/movie/${encodeURIComponent(movie.movie_name)}`}
                    className="group relative aspect-2/3 rounded-xl overflow-hidden bg-brand-wash border border-brand-border shadow-md"
                  >
                    <TMDBImage
                      path={movie.poster_url}
                      alt=""
                      fallbackAlt={movie.movie_name}
                      fill
                      className="object-cover transition-transform duration-500 group-hover:scale-110"
                      sizes="(max-width: 768px) 50vw, 33vw"
                      priority={idx < 2}
                    />
                    <div className="absolute inset-0 bg-linear-to-t from-black/90 via-black/20 to-transparent opacity-80 group-hover:opacity-100 transition-opacity" />
                    <div className="absolute bottom-0 left-0 right-0 p-3">
                      <h3 className="text-white font-bold text-sm leading-tight line-clamp-2 mb-1 group-hover:text-brand-accent transition-colors">
                        {movie.movie_name}
                      </h3>
                      <p className="text-zinc-300 text-xs font-medium">{movie.movie_year}</p>
                    </div>
                  </Link>
                ))}
              </div>
            ) : (
              /* Rings List View */
              <div className="space-y-4">
                {ringtones.map((ringtone) => (
                  <RingtoneCard key={ringtone.id} ringtone={ringtone} />
                ))}
              </div>
            )}
          </>
        ) : (
          <div className="text-center py-12 text-zinc-500">
            <p>No ringtones found for this actor.</p>
          </div>
        )}
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect, useMemo } from 'react';
import { createBrowserClient } from '@supabase/ssr';
import { Loader2, Download, RefreshCcw } from 'lucide-react';
import { useSearchParams } from 'next/navigation';

const ITEMS_PER_PAGE = 20;

type DownloadLog = {
    id: string;
    created_at: string;
    ringtone_id: string;
    user_id: string | null;
    ip_address?: string;
    ringtones: {
        title: string;
        movie_name: string;
    } | null;
};

export default function DownloadActivity() {
    const [logs, setLogs] = useState<DownloadLog[]>([]);
    const [loading, setLoading] = useState(true);
    const [page, setPage] = useState(1);
    const [totalCount, setTotalCount] = useState(0);

    const supabase = useMemo(() => createBrowserClient(
        process.env.NEXT_PUBLIC_SUPABASE_URL!,
        process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!
    ), []);

    useEffect(() => {
        fetchLogs();
    }, [page]);

    const fetchLogs = async () => {
        setLoading(true);
        try {
            const from = (page - 1) * ITEMS_PER_PAGE;
            const to = from + ITEMS_PER_PAGE - 1;

            const { data, count, error } = await supabase
                .from('download_logs')
                .select('*, ringtones ( title, movie_name )', { count: 'exact' })
                .order('created_at', { ascending: false })
                .range(from, to);

            if (error) {
                console.error('Error fetching download logs:', error);
            } else {
                setLogs(data as any || []);
                setTotalCount(count || 0);
            }
        } catch (err) {
            console.error('Unexpected error:', err);
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="space-y-6">
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-2xl font-bold text-slate-900">Download Activity</h1>
                    <p className="text-slate-500 text-sm">Monitor recent ringtone downloads.</p>
                </div>
                <button
                    onClick={fetchLogs}
                    className="p-2 border border-slate-200 rounded-lg hover:border-indigo-300 hover:text-indigo-600 transition-colors"
                >
                    <RefreshCcw size={18} className={loading ? 'animate-spin' : ''} />
                </button>
            </div>

            {loading && logs.length === 0 ? (
                <div className="flex justify-center p-12">
                    <Loader2 className="animate-spin text-indigo-600" size={32} />
                </div>
            ) : (
                <div className="bg-white border border-slate-200 rounded-2xl overflow-hidden shadow-sm">
                    <div className="overflow-x-auto">
                        <table className="w-full text-left text-sm">
                            <thead className="bg-slate-50 text-slate-500 uppercase font-bold text-xs border-b border-slate-200">
                                <tr>
                                    <th className="p-4">Ringtone</th>
                                    <th className="p-4">Downloaded At</th>
                                    <th className="p-4">User / IP</th>
                                    <th className="p-4 text-right">ID</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-100">
                                {logs.length === 0 ? (
                                    <tr>
                                        <td colSpan={4} className="p-8 text-center text-slate-500">
                                            No download activity found.
                                        </td>
                                    </tr>
                                ) : logs.map((log) => (
                                    <tr key={log.id} className="hover:bg-slate-50 transition-colors">
                                        <td className="p-4">
                                            {log.ringtones ? (
                                                <div>
                                                    <p className="font-medium text-slate-900">{log.ringtones.title}</p>
                                                    <p className="text-xs text-slate-500">{log.ringtones.movie_name}</p>
                                                </div>
                                            ) : (
                                                <span className="text-slate-400 italic">Unknown Ringtone ({log.ringtone_id})</span>
                                            )}
                                        </td>
                                        <td className="p-4 text-slate-600">
                                            {new Date(log.created_at).toLocaleString()}
                                        </td>
                                        <td className="p-4">
                                            <div className="flex flex-col">
                                                {log.user_id ? (
                                                    <span className="font-mono text-xs bg-indigo-50 text-indigo-600 px-1.5 py-0.5 rounded w-fit">
                                                        User: {log.user_id.substring(0, 8)}...
                                                    </span>
                                                ) : (
                                                    <span className="text-slate-400 text-xs">Guest</span>
                                                )}
                                                {log.ip_address && (
                                                    <span className="text-slate-400 text-[10px] font-mono mt-0.5">{log.ip_address}</span>
                                                )}
                                            </div>
                                        </td>
                                        <td className="p-4 text-right font-mono text-xs text-slate-400">
                                            {log.id.substring(0, 8)}
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                    {/* Pagination */}
                    <div className="p-4 border-t border-slate-200 flex justify-between items-center text-xs text-slate-500">
                        <span>Showing {logs.length} entries (Page {page})</span>
                        <div className="flex gap-2">
                            <button
                                disabled={page === 1}
                                onClick={() => setPage(p => Math.max(1, p - 1))}
                                className="px-3 py-1 rounded bg-slate-50 border border-slate-200 disabled:opacity-50"
                            >
                                Prev
                            </button>
                            <button
                                disabled={logs.length < ITEMS_PER_PAGE}
                                onClick={() => setPage(p => p + 1)}
                                className="px-3 py-1 rounded bg-slate-50 border border-slate-200 disabled:opacity-50"
                            >
                                Next
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}

'use client';

import { useState, useEffect, useMemo } from 'react';
import { createBrowserClient } from '@supabase/ssr';
import { Loader2, Search, Upload, Trash2, Plus } from 'lucide-react';
import Image from 'next/image';
import { DEITY_CATEGORIES } from '@/lib/constants';

interface DeityImage {
    id: string;
    deity_name: string;
    image_url: string;
    created_at: string;
}

export default function DeityManagement() {
    const [deities, setDeities] = useState<DeityImage[]>([]);
    const [loading, setLoading] = useState(true);
    const [search, setSearch] = useState('');

    // Upload State
    const [isUploading, setIsUploading] = useState(false);
    const [newDeityName, setNewDeityName] = useState('');
    const [file, setFile] = useState<File | null>(null);

    const supabase = useMemo(() => createBrowserClient(
        process.env.NEXT_PUBLIC_SUPABASE_URL!,
        process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!
    ), []);

    const [potentialDeities, setPotentialDeities] = useState<string[]>([]);

    useEffect(() => {
        fetchDeities();

        // Flatten and sort the hardcoded categories
        const allDeities = Object.values(DEITY_CATEGORIES).flat().sort() as string[];
        setPotentialDeities(allDeities);
    }, [supabase]);

    const fetchDeities = async () => {
        setLoading(true);
        const { data } = await supabase
            .from('deity_images')
            .select('*')
            .order('created_at', { ascending: false });

        if (data) setDeities(data as DeityImage[]);
        setLoading(false);
    };

    const handleUpload = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!file || !newDeityName.trim()) return;

        setIsUploading(true);
        try {
            // 1. Upload Image
            const fileExt = file.name.split('.').pop();
            const fileName = `${Date.now()}.${fileExt}`;
            const filePath = `${fileName}`;

            // Check if 'deities' bucket exists, if not it might fail.
            const { error: uploadError } = await supabase.storage
                .from('deities')
                .upload(filePath, file);

            if (uploadError) throw uploadError;

            // 2. Get Public URL
            const { data: { publicUrl } } = supabase.storage
                .from('deities')
                .getPublicUrl(filePath);

            // 3. Save to DB
            const { data: inserted, error: dbError } = await supabase
                .from('deity_images')
                .insert({
                    deity_name: newDeityName.trim(),
                    image_url: publicUrl
                })
                .select()
                .single();

            if (dbError) throw dbError;

            if (inserted) {
                setDeities(prev => [inserted as DeityImage, ...prev]);
                setNewDeityName('');
                setFile(null);
                alert('Deity image added successfully!');
            }

        } catch (error: any) {
            console.error("Upload error:", error);
            alert(`Failed to upload: ${error.message}`);
        } finally {
            setIsUploading(false);
        }
    };

    const handleDelete = async (id: string, name: string) => {
        if (!confirm(`Delete image for ${name}?`)) return;

        const { error } = await supabase.from('deity_images').delete().eq('id', id);
        if (!error) {
            setDeities(prev => prev.filter(a => a.id !== id));
        } else {
            alert("Failed to delete.");
        }
    };

    const filteredDeities = deities.filter(a =>
        a.deity_name.toLowerCase().includes(search.toLowerCase())
    );

    return (
        <div className="space-y-8">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                <div>
                    <h1 className="text-2xl font-bold text-white">Deity Images</h1>
                    <p className="text-zinc-400 text-sm">Upload images for Deities/Gods.</p>
                </div>
            </div>

            {/* Upload Section */}
            <div className="bg-white border border-slate-200 rounded-2xl p-6 shadow-sm">
                <h3 className="text-lg font-bold text-slate-900 mb-4 flex items-center gap-2">
                    <Plus size={20} className="text-indigo-600" /> Add New Deity Image
                </h3>
                <form onSubmit={handleUpload} className="flex flex-col md:flex-row gap-4 items-end">
                    <div className="w-full md:flex-1 space-y-2">
                        <label className="text-xs font-bold text-slate-500 uppercase">Deity Name (Select or Type)</label>
                        <input
                            type="text"
                            list="deity-names"
                            value={newDeityName}
                            onChange={e => setNewDeityName(e.target.value)}
                            placeholder="e.g. Lord Murugan"
                            className="w-full bg-slate-50 border border-slate-200 rounded-lg px-4 py-2.5 text-sm text-slate-900 focus:border-indigo-500/50 outline-none"
                            required
                        />
                        <datalist id="deity-names">
                            {potentialDeities.map(name => (
                                <option key={name} value={name} />
                            ))}
                        </datalist>

                        {/* Quick Pick List */}
                        {potentialDeities.length > 0 && (
                            <div className="mt-2">
                                <p className="text-[10px] text-zinc-400 font-bold uppercase mb-1">Quick Select (Deities needing images):</p>
                                <div className="flex flex-wrap gap-2 max-h-32 overflow-y-auto">
                                    {potentialDeities.map(name => {
                                        // Check if this deity already has an image uploaded
                                        const hasImage = deities.some(d => d.deity_name.toLowerCase() === name.toLowerCase());
                                        if (hasImage) return null; // Skip if already uploaded

                                        return (
                                            <button
                                                key={name}
                                                type="button"
                                                onClick={() => setNewDeityName(name)}
                                                className="px-2 py-1 bg-indigo-50 hover:bg-indigo-100 text-indigo-700 text-xs rounded-md transition-colors border border-indigo-100"
                                            >
                                                {name}
                                            </button>
                                        );
                                    })}
                                </div>
                            </div>
                        )}
                    </div>
                    <div className="w-full md:w-auto space-y-2">
                        <label className="text-xs font-bold text-slate-500 uppercase">Image</label>
                        <label className="flex items-center gap-2 cursor-pointer bg-slate-50 border border-slate-200 rounded-lg px-4 py-2 hover:bg-slate-100 transition-colors">
                            <Upload size={18} className="text-slate-400" />
