                                    <th className="p-4">Joined</th>
                                    <th className="p-4 text-right pr-6">Actions</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-100">
                                {filteredUsers.length === 0 ? (
                                    <tr>
                                        <td colSpan={5} className="p-8 text-center text-slate-500">No users found.</td>
                                    </tr>
                                ) : filteredUsers.map((user) => (
                                    <tr key={user.id} className="hover:bg-slate-50 transition-colors">
                                        <td className="p-4 pl-6">
                                            <div className="flex items-center gap-3">
                                                <div className="relative w-10 h-10 rounded-full overflow-hidden bg-slate-100 shrink-0 border border-slate-200">
                                                    {user.avatar_url ? (
                                                        <Image src={user.avatar_url} alt="avatar" fill className="object-cover" />
                                                    ) : (
                                                        <div className="w-full h-full flex items-center justify-center text-slate-400">
                                                            <UserIcon size={20} />
                                                        </div>
                                                    )}
                                                </div>
                                                <div>
                                                    <button onClick={() => setSelectedUser(user)} className="text-sm font-bold text-slate-900 hover:text-indigo-600 transition-colors text-left">
                                                        {user.full_name || 'No Name'}
                                                    </button>
                                                    <p className="text-xs text-slate-500 font-mono">{user.email}</p>
                                                </div>
                                            </div>
                                        </td>
                                        <td className="p-4">
                                            <span className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded text-[10px] font-bold uppercase tracking-wider
                            ${user.role === 'admin' ? 'bg-purple-50 text-purple-600 border border-purple-200' : 'bg-slate-100 text-slate-500 border border-slate-200'}`}>
                                                {user.role === 'admin' && <Shield size={12} />}
                                                {user.role || 'USER'}
                                            </span>
                                        </td>
                                        <td className="p-4">
                                            <div className="flex items-center gap-3">
                                                <div className="text-xs">
                                                    <span className="text-emerald-600 font-bold block">{user.points || 0} PTS</span>
                                                    <span className="text-slate-500 block">Lvl {user.level || 1}</span>
                                                </div>
                                                <div className="text-[10px] px-2 py-0.5 rounded bg-amber-50 text-amber-600 border border-amber-200 font-medium">
                                                    {getLevelTitle(user.level || 1)}
                                                </div>
                                            </div>
                                        </td>
                                        <td className="p-4">
                                            <span className="text-xs text-slate-500">
                                                {user.created_at ? new Date(user.created_at).toLocaleDateString() : 'Unknown'}
                                            </span>
                                        </td>
                                        <td className="p-4 text-right pr-6">
                                            <div className="flex items-center justify-end gap-2">
                                                <button
                                                    onClick={() => setSelectedUser(user)}
                                                    className="p-2 hover:bg-slate-100 rounded-lg text-slate-400 hover:text-indigo-600 transition-colors"
                                                    title="View Full Profile & Finances"
                                                >
                                                    <Eye size={18} />
                                                </button>
                                                <Link
                                                    href={`/admin/ringtones?user_id=${user.id}`}
                                                    className="p-2 hover:bg-slate-100 rounded-lg text-slate-400 hover:text-indigo-600 transition-colors"
                                                    title="View Ringtones"
                                                >
                                                    <Music size={16} />
                                                </Link>
                                                <button
                                                    onClick={() => toggleAdmin(user)}
                                                    className={`text-xs font-medium px-3 py-1.5 rounded-lg border transition-colors
                                    ${user.role === 'admin'
                                                            ? 'bg-red-50 text-red-600 border-red-200 hover:bg-red-100'
                                                            : 'bg-indigo-50 text-indigo-600 border-indigo-200 hover:bg-indigo-100'
                                                        }
                                `}
                                                >
                                                    {user.role === 'admin' ? 'Revoke Admin' : 'Make Admin'}
                                                </button>
                                            </div>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </>
            )}

            {/* User Detail Modal */}
            {selectedUser && (
                <UserDetailModal
                    user={selectedUser}
                    onClose={() => setSelectedUser(null)}
                    supabase={supabase}
                />
            )}
        </div>
    );
}

function UserDetailModal({ user, onClose, supabase }: { user: Profile, onClose: () => void, supabase: any }) {
    const [loading, setLoading] = useState(true);
    const [withdrawals, setWithdrawals] = useState<Withdrawal[]>([]);
    const [requests, setRequests] = useState<any[]>([]);
    const [uploads, setUploads] = useState<Ringtone[]>([]);
    const [stats, setStats] = useState<any>(null);

    useEffect(() => {
        async function loadData() {
            setLoading(true);
            try {
                // Fetch extra data
                const [withdrawalsRes, requestsRes, uploadsRes, gamificationRes] = await Promise.all([
                    supabase.from('withdrawals').select('*').eq('user_id', user.id).order('created_at', { ascending: false }),
                    supabase.from('ringtone_requests').select('*').eq('user_id', user.id).order('created_at', { ascending: false }),
                    supabase.from('ringtones').select('*').eq('user_id', user.id).eq('status', 'approved').order('created_at', { ascending: false }),
                    syncUserGamification(supabase, user.id)
                ]);

                if (withdrawalsRes.data) setWithdrawals(withdrawalsRes.data);
                if (requestsRes.data) setRequests(requestsRes.data);
                if (uploadsRes.data) setUploads(uploadsRes.data);
                if (gamificationRes) setStats(gamificationRes);

            } catch (err) {
                console.error("Error loading user details:", err);
            } finally {
                setLoading(false);
            }
        }
        loadData();
    }, [user.id, supabase]);

    const transactions = [
        ...uploads.map(u => ({
            type: 'upload',
            title: u.title,
            amount: 10,
            date: u.created_at,
            status: 'completed',
            utr: undefined as string | undefined
        })),
        ...withdrawals.map(w => ({
            type: 'withdrawal',
            title: 'Withdrawal',
            amount: -w.amount,
            date: w.created_at,
            status: w.status,
            utr: (w as any).transaction_id as string | undefined
        })),
        ...requests.map(r => ({
            type: 'request',
            title: `Request: ${r.song_name}`,
            amount: -10,
            date: r.created_at,
            status: r.status === 'fulfilled' ? 'completed' : 'pending',
            utr: undefined as string | undefined
        }))
    ].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300">
            <div className="w-full max-w-2xl bg-white rounded-3xl overflow-hidden shadow-2xl flex flex-col max-h-[90vh]">
                {/* Modal Header */}
                <div className="p-6 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
                    <div className="flex items-center gap-4">
                        <div className="relative w-12 h-12 rounded-full overflow-hidden bg-slate-200 border-2 border-white shadow-sm">
                            {user.avatar_url ? (
                                <Image src={user.avatar_url} alt="avatar" fill className="object-cover" />
                            ) : (
                                <div className="w-full h-full flex items-center justify-center text-slate-400">
                                    <UserIcon size={24} />
                                </div>
                            )}
                        </div>
                        <div>
                            <h2 className="text-xl font-bold text-slate-900 leading-tight">{user.full_name || 'No Name'}</h2>
                            <p className="text-xs text-slate-500 font-mono">{user.email}</p>
                        </div>
                    </div>
                    <button onClick={onClose} className="p-2 hover:bg-slate-200/50 rounded-full transition-colors text-slate-400">
                        <X size={24} />
                    </button>
                </div>

                <div className="flex-1 overflow-y-auto p-6 space-y-8">
                    {loading ? (
                        <div className="flex flex-col items-center justify-center py-20 gap-4">
                            <Loader2 className="animate-spin text-indigo-600" size={40} />
                            <p className="text-slate-500 font-mono text-xs uppercase tracking-widest">Crunching User Data...</p>
                        </div>
                    ) : (
                        <>
                            {/* Profile Grid */}
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                <div className="space-y-4">
                                    <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
                                        <UserIcon size={12} /> User Info
                                    </h3>
                                    <div className="bg-slate-50 rounded-2xl p-4 border border-slate-100 space-y-3">
                                        <div className="flex justify-between items-center text-sm">
                                            <span className="text-slate-500">UPI ID</span>
                                            <span className="font-bold text-slate-900 font-mono text-xs">{user.upi_id || 'Not Set'}</span>
                                        </div>
                                        <div className="flex justify-between items-center text-sm">
                                            <span className="text-slate-500">Instagram</span>
                                            <span className="font-bold text-slate-900 text-xs">{user.instagram_handle || 'N/A'}</span>
                                        </div>
                                        <div className="flex justify-between items-center text-sm">
                                            <span className="text-slate-500">Twitter</span>
                                            <span className="font-bold text-slate-900 text-xs">{user.twitter_handle || 'N/A'}</span>
                                        </div>
                                        <div className="flex justify-between items-center text-sm pt-2 border-t border-slate-200/50">
                                            <span className="text-slate-500">Member Since</span>
                                            <span className="font-bold text-slate-900 text-xs">{new Date(user.created_at).toLocaleDateString()}</span>
                                        </div>
                                    </div>
                                </div>

                                <div className="space-y-4">
                                    <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
                                        <Wallet size={12} /> Financial Stats
                                    </h3>
                                    <div className="bg-indigo-50 border border-indigo-100 rounded-2xl p-4 space-y-3">
                                        <div className="flex justify-between items-center">
                                            <span className="text-indigo-600 text-xs font-bold uppercase tracking-tight">Current Rep</span>
                                            <span className="text-2xl font-black text-indigo-700">₹{stats?.points || 0}</span>
                                        </div>
                                        <div className="h-px bg-indigo-200/50" />
                                        <div className="grid grid-cols-2 gap-4">
                                            <div>
                                                <p className="text-[9px] text-indigo-400 font-bold uppercase">Lifetime</p>
                                                <p className="text-sm font-black text-indigo-600">₹{stats?.lifetimePoints || 0}</p>
                                            </div>
                                            <div className="text-right">
                                                <p className="text-[9px] text-indigo-400 font-bold uppercase">Withdrawn</p>
                                                <p className="text-sm font-black text-indigo-600">₹{stats?.totalWithdrawn || 0}</p>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            </div>

                            {/* Transaction History */}
                            <div className="space-y-4">
                                <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
                                    <History size={12} /> Ledger
                                </h3>
                                <div className="space-y-2">
                                    {transactions.length === 0 ? (
                                        <div className="text-center py-10 bg-slate-50 rounded-2xl border border-dashed border-slate-200">
                                            <p className="text-slate-400 text-xs font-bold uppercase tracking-widest">No transaction history</p>
                                        </div>
                                    ) : transactions.map((t, i) => (
                                        <div key={i} className="flex items-center justify-between p-3 bg-white border border-slate-100 rounded-xl hover:border-indigo-200 transition-colors group">
                                            <div className="flex items-center gap-3">
                                                <div className={`w-8 h-8 rounded-lg flex items-center justify-center shrink-0
                                                    ${t.type === 'upload' ? 'bg-emerald-50 text-emerald-500' :
                                                        t.type === 'withdrawal' ? 'bg-amber-50 text-amber-500' :
                                                            'bg-blue-50 text-blue-500'}`}>
                                                    {t.type === 'upload' ? <CloudUpload size={14} /> :
                                                        t.type === 'withdrawal' ? <Wallet size={14} /> :
                                                            <Star size={14} />}
                                                </div>
                                                <div className="min-w-0">
                                                    <p className="text-xs font-bold text-slate-900 truncate">{t.title}</p>
                                                    <div className="flex items-center gap-2 mt-0.5">
                                                        <span className="text-[9px] text-slate-400">{new Date(t.date).toLocaleDateString()}</span>
                                                        {t.utr && (
                                                            <span className="text-[9px] font-black text-indigo-500 bg-indigo-50 px-1.5 py-0.5 rounded uppercase tracking-tighter">
                                                                UTR: {t.utr}
                                                            </span>
                                                        )}
                                                    </div>
                                                </div>
                                            </div>
                                            <div className="text-right">
                                                <p className={`text-xs font-black ${t.amount > 0 ? 'text-emerald-500' : 'text-slate-900'}`}>
                                                    {t.amount > 0 ? '+' : ''}{t.amount}
                                                </p>
                                                <span className={`text-[8px] font-black uppercase tracking-tighter
                                                    ${t.status === 'completed' || t.status === 'fulfilled' ? 'text-emerald-500' :
                                                        t.status === 'rejected' ? 'text-red-500' :
                                                            'text-amber-500 animate-pulse'}`}>
                                                    {t.status}
                                                </span>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        </>
                    )}
                </div>

                {/* Modal Footer */}
                <div className="p-4 bg-slate-50 border-t border-slate-100 flex justify-end gap-3">
                    <Link
                        href={`/admin/ringtones?user_id=${user.id}`}
                        className="px-4 py-2 bg-white border border-slate-200 rounded-xl text-xs font-bold text-slate-600 hover:bg-slate-50 transition-all flex items-center gap-2"
                    >
                        <Music size={14} />
                        Ringtones
                    </Link>
                    <button
                        onClick={onClose}
                        className="px-6 py-2 bg-slate-900 text-white rounded-xl text-xs font-bold hover:bg-slate-800 transition-all shadow-lg shadow-slate-900/10"
                    >
                        Close
                    </button>
                </div>
            </div>
        </div>
    );
}

'use client';

import { useEffect, useState, useCallback, useMemo } from 'react';
import { createBrowserClient } from '@supabase/ssr';
import { Loader2, TrendingUp, CircleCheck, CircleX, User, Clock, Search, CircleAlert } from 'lucide-react';
import { updateWithdrawalStatus } from '@/app/actions/admin';
import Image from 'next/image';
import { Withdrawal } from '@/types';

export default function AdminWithdrawals() {
    const [loading, setLoading] = useState(true);
    const [withdrawals, setWithdrawals] = useState<Withdrawal[]>([]);
    const [filter, setFilter] = useState<'pending' | 'completed' | 'rejected'>('pending');
    const [searchQuery, setSearchQuery] = useState('');
    const [processingId, setProcessingId] = useState<string | null>(null);

    const supabase = useMemo(() => createBrowserClient(
        process.env.NEXT_PUBLIC_SUPABASE_URL!,
        process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!
    ), []);

    const fetchWithdrawals = useCallback(async () => {
        setLoading(true);
        try {
            console.log("Fetching withdrawals for status:", filter);
            const { data, error } = await supabase
                .from('withdrawals')
                .select(`
                    *,
                    profile:profiles!user_id (
                        full_name,
                        avatar_url,
                        points
                    )
                `)
                .eq('status', filter)
                .order('created_at', { ascending: false });

            if (error) {
                console.error("Supabase Error fetching withdrawals (Relations):", error);
                // Fallback: Fetch without relation if relation fails
                const { data: fallbackData, error: fallbackError } = await supabase
                    .from('withdrawals')
                    .select('*')
                    .eq('status', filter)
                    .order('created_at', { ascending: false });

                if (fallbackError) {
                    console.error("Critical: Fallback fetch also failed:", fallbackError);
                    throw fallbackError;
                }
                console.warn("Fallback fetch successful. Relations might be broken.", fallbackData);
                // Manually map to prevent UI crash
                const mapped = fallbackData?.map(w => ({ ...w, profile: { full_name: 'Unknown User (Join Failed)', avatar_url: null, points: 0 } }));
                setWithdrawals((mapped as unknown as Withdrawal[]) || []);
                return;
            }

            console.log("Withdrawals fetched successfully:", data?.length);
            setWithdrawals((data as unknown as Withdrawal[]) || []);
        } catch (error) {
            console.error("Error fetching withdrawals:", error);
        } finally {
            setLoading(false);
        }
    }, [filter]);

    useEffect(() => {
        fetchWithdrawals();
    }, [fetchWithdrawals]);

    const handleAction = async (id: string, status: 'completed' | 'rejected', transactionId?: string) => {
        if (!confirm(`Are you sure you want to mark this as ${status}?`)) return;

        setProcessingId(id);
        try {
            const res = await updateWithdrawalStatus(id, status, transactionId);
            if (res.success) {
                setWithdrawals(prev => prev.filter(w => w.id !== id));
            } else {
                alert(res.error || 'Failed to update status');
            }
        } catch (err) {
            alert('An error occurred');
        } finally {
            setProcessingId(null);
        }
    };

    const filteredWithdrawals = withdrawals.filter(w =>
        w.upi_id?.toLowerCase().includes(searchQuery.toLowerCase()) ||
        w.profile?.full_name?.toLowerCase().includes(searchQuery.toLowerCase())
    );

    return (
        <div className="space-y-8 pb-20">
            {/* Header */}
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div>
                    <h1 className="text-3xl font-bold text-slate-900 mb-2 tracking-tight">Withdrawal Requests</h1>
                    <p className="text-slate-500 text-sm">Process and manage user payout requests.</p>
                </div>

                <div className="flex items-center gap-2 bg-slate-100 p-1 rounded-xl border border-slate-200">
                    {(['pending', 'completed', 'rejected'] as const).map((t) => (
                        <button
                            key={t}
                            onClick={() => setFilter(t)}
                            className={`px-4 py-2 rounded-lg text-xs font-bold uppercase tracking-wider transition-all
                                ${filter === t
                                    ? 'bg-white text-indigo-600 shadow-sm'
                                    : 'text-slate-500 hover:text-slate-900'}`}
                        >
                            {t}
                        </button>
                    ))}
                </div>
            </div>

            {/* Filters */}
            <div className="relative max-w-md group">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-indigo-600 transition-colors" size={18} />
                <input
                    type="text"
                    placeholder="Search by User or UPI ID..."
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    className="w-full bg-white border border-slate-200 rounded-xl py-3 pl-10 pr-4 text-sm text-slate-900 focus:border-indigo-500 outline-none transition-all placeholder:text-slate-400 shadow-sm"
                />
            </div>

            {/* List */}
            {loading ? (
                <div className="flex flex-col items-center justify-center py-20 gap-4">
                    <Loader2 className="animate-spin text-indigo-600" size={32} />
                    <p className="text-slate-500 font-mono text-xs uppercase tracking-widest">Fetching Ledgers...</p>
                </div>
            ) : filteredWithdrawals.length === 0 ? (
                <div className="text-center py-20 bg-white border border-dashed border-slate-200 rounded-3xl">
                    <TrendingUp size={48} className="mx-auto text-slate-300 mb-4" />
                    <p className="text-slate-500 font-medium">No withdrawal requests found.</p>
                </div>
            ) : (
                <div className="grid grid-cols-1 gap-4">
                    {filteredWithdrawals.map((w) => (
                        <div key={w.id} className="bg-white border border-slate-200 rounded-2xl p-5 hover:border-indigo-200 transition-all group shadow-sm">
                            <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
                                <div className="flex items-center gap-4">
                                    <div className="w-12 h-12 rounded-full overflow-hidden bg-slate-100 shrink-0 border border-slate-200">
                                        {w.profile?.avatar_url ? (
                                            <Image src={w.profile.avatar_url} alt="User" width={48} height={48} className="object-cover" />
                                        ) : (
                                            <div className="w-full h-full flex items-center justify-center text-slate-400">
                                                <User size={20} />
                                            </div>
                                        )}
                                    </div>
                                    <div>
                                        <h3 className="font-bold text-slate-900 mb-0.5">{w.profile?.full_name || 'Legacy User'}</h3>
                                        <div className="flex items-center gap-3 text-xs">
                                            <span className="text-indigo-600 font-mono font-bold">UPI: {w.upi_id}</span>
                                            <span className="text-slate-300">•</span>
                                            <span className="text-slate-500 flex items-center gap-1">
                                                <Clock size={12} />
                                                {new Date(w.created_at).toLocaleDateString()}
                                            </span>
                                        </div>
                                    </div>
                                </div>

                                <div className="flex items-center justify-between md:justify-end gap-x-8 gap-y-4 w-full md:w-auto">
                                    <div className="text-right">
                                        <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1">Payout Amount</p>
                                        <p className="text-2xl font-black text-slate-900">₹{w.amount}</p>
                                    </div>

                                    {filter === 'pending' && (
                                        <div className="flex flex-col gap-2">
                                            <input
                                                type="text"
                                                id={`utr-${w.id}`}
                                                placeholder="UTR / Trans. ID"
                                                className="w-32 bg-slate-50 border border-slate-200 rounded-lg px-2 py-1.5 text-[10px] outline-none focus:border-indigo-400 font-mono"
                                            />
                                            <div className="flex gap-2">
                                                <button
                                                    disabled={processingId === w.id}
                                                    onClick={() => {
                                                        const utr = (document.getElementById(`utr-${w.id}`) as HTMLInputElement)?.value;
                                                        handleAction(w.id, 'completed', utr);
                                                    }}
                                                    className="h-9 px-4 bg-emerald-500 text-white font-black text-[10px] uppercase tracking-widest rounded-lg hover:bg-emerald-600 transition-all disabled:opacity-50 flex items-center gap-2 shadow-sm shadow-emerald-500/20"
                                                >
                                                    {processingId === w.id ? <Loader2 size={12} className="animate-spin" /> : <CircleCheck size={12} />}
                                                    Mark Paid
                                                </button>
                                                <button
                                                    disabled={processingId === w.id}
                                                    onClick={() => handleAction(w.id, 'rejected')}
                                                    className="h-9 px-3 bg-red-50 text-red-600 font-black text-[10px] uppercase tracking-widest rounded-lg hover:bg-red-100 transition-all disabled:opacity-50 flex items-center gap-2 border border-red-200"
                                                >
                                                    <CircleX size={12} />
                                                    Reject
                                                </button>
                                            </div>
                                        </div>
                                    )}

                                    {filter !== 'pending' && (
                                        <div className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest border
                                            ${filter === 'completed' ? 'bg-emerald-50 text-emerald-600 border-emerald-200' : 'bg-red-50 text-red-600 border-red-200'}`}>
                                            {filter}
                                        </div>
                                    )}
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            )}

            {/* Summary Banner */}
            {filter === 'pending' && filteredWithdrawals.length > 0 && (
                <div className="fixed bottom-6 left-1/2 -translate-x-1/2 md:left-auto md:right-12 md:translate-x-0 z-50 animate-in fade-in slide-in-from-bottom-4 duration-500">
                    <div className="bg-slate-900 text-white px-8 py-4 rounded-2xl shadow-2xl flex items-center gap-6 border border-slate-800">
                        <div className="flex flex-col">
                            <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Total Payout Pending</span>
