'use client';

import { useState, useRef, useEffect } from 'react';
import { createBrowserClient } from '@supabase/ssr';
import { Camera, Upload, X, Loader2 } from 'lucide-react';
import { useRouter } from 'next/navigation';

interface DeityImageUploadProps {
    deityName: string;
    currentImage?: string;
    onUploadSuccess?: () => void;
}

export default function DeityImageUpload({ deityName, currentImage, onUploadSuccess }: DeityImageUploadProps) {
    const [isAdmin, setIsAdmin] = useState(false);
    const [uploading, setUploading] = useState(false);
    const [isOpen, setIsOpen] = useState(false);
    const fileInputRef = useRef<HTMLInputElement>(null);
    const router = useRouter();

    const supabase = createBrowserClient(
        process.env.NEXT_PUBLIC_SUPABASE_URL!,
        process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!
    );

    useEffect(() => {
        const checkAdmin = async () => {
            const { data: { user } } = await supabase.auth.getUser();
            if (!user) return;

            const { data: profile } = await supabase
                .from('profiles')
                .select('role')
                .eq('id', user.id)
                .single();

            if (profile?.role === 'admin') {
                setIsAdmin(true);
            }
        };
        checkAdmin();
    }, [supabase]);

    const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        setUploading(true);
        try {
            // 1. Upload to Storage
            const fileExt = file.name.split('.').pop();
            const fileName = `${deityName.replace(/[^a-z0-9]/gi, '_').toLowerCase()}-${Date.now()}.${fileExt}`;
            const filePath = `${fileName}`;

            // Ensure bucket is 'deities'
            const { error: uploadError } = await supabase.storage
                .from('deities')
                .upload(filePath, file);

            if (uploadError) throw uploadError;

            // 2. Get Public URL
            const { data: { publicUrl } } = supabase.storage
                .from('deities')
                .getPublicUrl(filePath);

            // 3. Update Database (Insert or Update)
            const { error: dbError } = await supabase
                .from('deity_images')
                .upsert({
                    deity_name: deityName,
                    image_url: publicUrl
                }, { onConflict: 'deity_name' });

            if (dbError) throw dbError;

            // Optional: revalidate cache action if it exists, otherwise router.refresh suffices mostly
            // await revalidateDeityCache(); 

            alert('Deity image updated successfully!');
            setIsOpen(false);
            router.refresh(); // Refresh server components
            if (onUploadSuccess) onUploadSuccess();

        } catch (error: any) {
            console.error('Upload failed:', error);
            alert(`Upload failed: ${error.message}`);
        } finally {
            setUploading(false);
        }
    };

    // If not admin, do not render anything
    if (!isAdmin) return null;

    return (
        <>
            {/* Edit Button (Visible only to admins) */}
            <button
                onClick={() => setIsOpen(true)}
                className="absolute bottom-2 right-2 bg-black/80 p-2 rounded-full text-white hover:bg-emerald-500 hover:text-black transition-colors shadow-lg z-20 backdrop-blur-sm border border-white/10"
                title="Change Deity Image"
            >
                <Camera size={16} />
            </button>

            {/* Modal */}
            {isOpen && (
                <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm">
                    <div className="bg-neutral-900 border border-neutral-800 rounded-xl p-6 w-full max-w-sm relative shadow-2xl">
                        <button
