                            className="absolute top-4 right-4 text-zinc-500 hover:text-white"
                        >
                            <X size={20} />
                        </button>

                        <h3 className="text-lg font-bold text-white mb-4">Update Deity Photo</h3>
                        <p className="text-zinc-400 text-sm mb-6">
                            Upload a new photo for <span className="text-emerald-400 font-bold">{deityName}</span>.
