                    colorClass="bg-linear-to-br from-cyan-500 to-blue-600 shadow-lg shadow-cyan-500/30"
                    gradientClass="bg-linear-to-br from-cyan-500/5 to-blue-500/5"
                    shadowClass="hover:shadow-cyan-500/20"
