                        index={idx}
                        name={singer.name}
                        image={singer.image}
                        href={`/artist/${encodeURIComponent(singer.name)}`}
                        priority={idx < 4}
                        className="md:w-full md:h-auto md:aspect-2/3"
                    />
                ))}
            </div>
        </div>
    );
}

