type ApiHandler = () => Promise<NextResponse>;

export async function apiHandler(handler: ApiHandler): Promise<NextResponse> {
    try {
        return await handler();
    } catch (error: any) {
        console.error('API Error:', error);

        if (error instanceof AppError) {
