import { cache as redisClient } from './redis';
import { CacheTTL } from './cache-keys';

/**
 * Cache service with advanced features
 * - Get/Set/Delete operations
 * - Batch operations
 * - Cache warming
 * - Graceful fallbacks
 */

export interface CacheOptions {
    ttl?: number;
    tags?: string[];
}

export interface CacheStats {
    hits: number;
    misses: number;
    errors: number;
}

// In-memory stats tracking
const stats: CacheStats = {
    hits: 0,
    misses: 0,
    errors: 0,
};

/**
 * Get value from cache
 */
export async function cacheGet<T>(key: string): Promise<T | null> {
    if (!redisClient) {
        stats.misses++;
        return null;
    }

    try {
        const value = await redisClient.get<T>(key);

        if (value !== null) {
            stats.hits++;
            console.log(`[Cache HIT] ${key}`);
        } else {
            stats.misses++;
            console.log(`[Cache MISS] ${key}`);
        }

        return value;
    } catch (error) {
        stats.errors++;
        console.error(`[Cache Error] Get failed for ${key}:`, error);
        return null;
    }
}

/**
 * Set value in cache
 */
export async function cacheSet<T>(
    key: string,
    value: T,
    options: CacheOptions = {}
): Promise<boolean> {
    if (!redisClient) {
        return false;
    }

    const ttl = options.ttl || CacheTTL.MEDIUM;

    try {
        await redisClient.set(key, value, { ex: ttl });
        console.log(`[Cache SET] ${key} (TTL: ${ttl}s)`);
        return true;
    } catch (error) {
        stats.errors++;
        console.error(`[Cache Error] Set failed for ${key}:`, error);
        return false;
    }
}

/**
 * Delete value from cache
 */
export async function cacheDelete(key: string): Promise<boolean> {
    if (!redisClient) {
        return false;
    }

    try {
        await redisClient.del(key);
        console.log(`[Cache DELETE] ${key}`);
        return true;
    } catch (error) {
        stats.errors++;
        console.error(`[Cache Error] Delete failed for ${key}:`, error);
        return false;
    }
}

/**
 * Delete multiple keys matching a pattern
 */
export async function cacheDeletePattern(pattern: string): Promise<number> {
    if (!redisClient) {
        return 0;
    }

    try {
