        '@type': 'Person',
        name: artist.name,
        url: `${SITE_URL}/artist/${encodeURIComponent(artist.name)}`,
        image: artist.image_url,
        description: artist.description || `Tamil ${jobTitle}`,
        jobTitle,
        worksFor: {
            '@type': 'Organization',
            name: 'Tamil Film Industry',
        },
    };
}

